-- Ensayo reversible: PRUEBAS OK provoca rollback de todo el bloque.
do $$
declare a uuid;c uuid;s uuid;t uuid;p uuid;art uuid;o uuid;r uuid;f uuid;sol uuid:=gen_random_uuid();lote uuid:=gen_random_uuid();antes jsonb;despues jsonb;receptor text;otra uuid;importacion uuid;pago uuid;
begin
 select id into a from public.perfiles where activo and not debe_cambiar_contrasena and rol::text='admin' limit 1;
 select id into c from public.perfiles where activo and not debe_cambiar_contrasena and rol::text='corporativo' limit 1;
 select rfc into receptor from public.razones_sociales where principal and activa;
 if a is null or c is null or receptor is null then raise exception 'FALTAN DATOS: admin, corporativo y razón principal activos.';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);
 insert into public.sucursales(nombre) values('Origen ensayo '||sol) returning id into s;
 insert into public.sucursales(nombre) values('Destino ensayo '||sol) returning id into t;
 insert into public.proveedores(razon_social,rfc,regimen_fiscal,cuenta_pl) values('Corrección sucursal ensayo','CSU010101AB1','601','insumos') returning id into p;
 insert into public.articulos(nombre,unidad,tipo) values('Insumo corrección ensayo','kg','consumible') returning id into art;
 insert into public.ordenes_compra(proveedor_id,sucursal_id,rfc_receptor) values(p,s,receptor) returning id into o;
 insert into public.orden_renglones(orden_id,articulo_id,descripcion,cantidad,precio,tasa_iva) values(o,art,'Insumo',10,10,'0') returning id into r;
 set local role authenticated;
 perform public.confirmar_orden(o);
 perform public.registrar_recepcion_orden(o,public.hoy_mx()-2,'Recepción histórica ensayo',jsonb_build_array(jsonb_build_object('id',r,'cantidad',10)),lote);
 f:=public.facturar_orden(o);
 select jsonb_agg(to_jsonb(x) order by x.id) into antes from public.recepciones_app x where lote_id=lote;
 begin perform public.corregir_sucursal_orden(gen_random_uuid(),o,s,t,'');raise exception 'FALLÓ: motivo';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 perform public.corregir_sucursal_orden(sol,o,s,t,'Sucursal de recepción capturada incorrectamente');
 perform public.corregir_sucursal_orden(sol,o,s,t,'Sucursal de recepción capturada incorrectamente');
 if not exists(select 1 from public.ordenes_compra where id=o and sucursal_id=t) or not exists(select 1 from public.facturas where id=f and sucursal_id=t) then raise exception 'FALLÓ: orden y factura no se corrigieron juntas';end if;
 select jsonb_agg(to_jsonb(x) order by x.id) into despues from public.recepciones_app x where lote_id=lote;
 if antes is distinct from despues or public.recibido_renglon(r)<>10 then raise exception 'FALLÓ: alteró recepción original';end if;
 if (select count(*) from public.orden_sucursal_correcciones where id=sol)<>1 or (select count(*) from public.orden_historial where orden_id=o and evento='Sucursal corregida')<>1 or not exists(select 1 from public.compra_notas where factura_id=f and usuario_id=a and texto like 'Sucursal corregida%') then raise exception 'FALLÓ: historial o doble envío';end if;
 begin perform public.corregir_sucursal_orden(sol,o,s,null,'Datos cambiados');raise exception 'FALLÓ: reutilizó solicitud';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 begin perform public.corregir_sucursal_orden(gen_random_uuid(),o,s,s,'Pantalla desactualizada');raise exception 'FALLÓ: sobrescritura';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 begin update public.orden_sucursal_correcciones set motivo='Escritura directa' where id=sol;raise exception 'FALLÓ: escritura directa';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',json_build_object('sub',c,'role','authenticated')::text,true);
 if not exists(select 1 from public.orden_sucursal_correcciones where id=sol) then raise exception 'FALLÓ: corporativo consulta';end if;
 begin perform public.corregir_sucursal_orden(gen_random_uuid(),o,t,s,'No autorizado');raise exception 'FALLÓ: corporativo gestiona';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);
 -- Reserva vigente: la corrección debe ser atómica y no mover efectivo.
 reset role;
 insert into public.reservas_boveda(sucursal_id,factura_id,monto,motivo,fecha_pago,creado_por) values(t,f,1,'Reserva de ensayo',public.hoy_mx(),a);
 set local role authenticated;
 begin perform public.corregir_sucursal_orden(gen_random_uuid(),o,t,s,'Corrección con reserva');raise exception 'FALLÓ: movió reserva';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 if not exists(select 1 from public.ordenes_compra where id=o and sucursal_id=t) then raise exception 'FALLÓ: corrección parcial';end if;
 reset role;
 delete from public.reservas_boveda where factura_id=f;
 insert into public.importaciones_recepciones(archivo,renglones) values('ensayo.xlsx',1) returning id into importacion;
 insert into public.recepciones_dodo(sucursal_id,dodo_insumo_id,material,unidad,fecha,cantidad,precio,importacion_id,orden_renglon_id,clasificacion) values(t,sol::text,'Insumo','kg',public.hoy_mx(),1,10,importacion,r,'orden');
 set local role authenticated;
 begin perform public.corregir_sucursal_orden(gen_random_uuid(),o,t,s,'Corrección con Dodo IS');raise exception 'FALLÓ: movió origen Dodo IS';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 reset role;
 delete from public.recepciones_dodo where importacion_id=importacion;
 insert into public.pagos(proveedor_id,fecha,monto,forma) values(p,public.hoy_mx(),10,'transferencia') returning id into pago;
 insert into public.pago_aplicaciones(pago_id,factura_id,monto) values(pago,f,10);
 set local role authenticated;
 begin perform public.corregir_sucursal_orden(gen_random_uuid(),o,t,s,'Corrección con pago');raise exception 'FALLÓ: movió pago';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 reset role;
 update public.pagos set anulado_en=now(),anulado_por=a,motivo_anulacion='Anulación de ensayo' where id=pago;
 insert into public.ordenes_compra(proveedor_id,sucursal_id,rfc_receptor) values(p,t,receptor) returning id into otra;
 insert into public.factura_ordenes(factura_id,orden_id) values(f,otra);
 set local role authenticated;
 begin perform public.corregir_sucursal_orden(gen_random_uuid(),o,t,s,'Factura compartida');raise exception 'FALLÓ: movió factura compartida';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 reset role;
 delete from public.factura_ordenes where factura_id=f and orden_id=otra;
 update public.ordenes_compra set estado='cerrada' where id=o;
 set local role authenticated;
 perform public.corregir_sucursal_orden(gen_random_uuid(),o,t,s,'Corrección de orden cerrada');
 if not exists(select 1 from public.ordenes_compra where id=o and estado='cerrada' and sucursal_id=s) or public.recibido_renglon(r)<>10 then raise exception 'FALLÓ: orden cerrada o cantidades';end if;
 if has_function_privilege('anon','public.corregir_sucursal_orden(uuid,uuid,uuid,uuid,text)','execute') then raise exception 'FALLÓ: anónimo';end if;
 raise exception 'PRUEBAS OK — orden completa y cerrada · factura vinculada · recepción original intacta · motivo e historial · doble envío · sin sobrescritura · pagos y reservas protegidos · factura compartida protegida · origen Dodo IS conservado · corrección atómica · corporativo consulta · sin escritura directa · anónimo sin ejecución';
end $$;
